//! Cargo-driven `msacm32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x79460000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ff96000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ff96000000u64)),
        o => panic!("msacm32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:oldnames", "import:advapi32", "import:user32", "import:winmm", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["engine:wine", "engine:oldnames", "import:advapi32", "import:user32", "import:winmm", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["engine:wine", "engine:oldnames", "import:advapi32", "import:user32", "import:winmm", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/msacm32",
        "dll/win32/msacm32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NON_CONFORMING_SWPRINTFS",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("msacm32_shims", &["dll/win32/msacm32/driver.c", "dll/win32/msacm32/filter.c", "dll/win32/msacm32/format.c", "dll/win32/msacm32/internal.c", "dll/win32/msacm32/msacm32_main.c", "dll/win32/msacm32/pcmconverter.c", "dll/win32/msacm32/stream.c"])
        .rc("dll/win32/msacm32/msacm.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/msacm32/msacm32.spec", "msacm32.dll")
        .spec_stubs()
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
